const VIEW_BOX_WIDTH = 610;
const VIEW_BOX_HEIGHT = 793;

const MapPointInput = React.forwardRef((props, ref) => {
  const { attribute, disabled, intlLabel, intlDescription, name, onChange, required, value, error } = props;
  const { formatMessage } = useIntl();
  const point = value && typeof value.x === 'number' && typeof value.y === 'number' ? value : null;

  function handleClick(event) {
    if (disabled) return;
    const svg = event.currentTarget;
    const rect = svg.getBoundingClientRect();
    const x = Math.round(((event.clientX - rect.left) / rect.width) * VIEW_BOX_WIDTH);
    const y = Math.round(((event.clientY - rect.top) / rect.height) * VIEW_BOX_HEIGHT);
    onChange({ target: { name, type: attribute.type, value: { x, y } } });
  }

  function handleClear(event) {
    event.preventDefault();
    onChange({ target: { name, type: attribute.type, value: null } });
  }

  return (
    <div ref={ref}>
      <label htmlFor={name} style={{ fontWeight: 600, display: 'block', marginBottom: 4 }}>
        {intlLabel ? formatMessage(intlLabel) : name}
        {required ? ' *' : ''}
      </label>
      {intlDescription && (
        <p style={{ fontSize: 12, color: '#666', marginBottom: 8 }}>{formatMessage(intlDescription)}</p>
      )}
      <svg
        id={name}
        viewBox={`0 0 ${VIEW_BOX_WIDTH} ${VIEW_BOX_HEIGHT}`}
        width="100%"
        style={{
          maxWidth: 320,
          display: 'block',
          background: '#FDFAF5',
          border: '1px solid #dcdce4',
          borderRadius: 4,
          cursor: disabled ? 'default' : 'crosshair',
        }}
        onClick={handleClick}
      >
        <g>
          {REGION_PATHS.map((d, index) => (
            <path key={index} d={d} fill="#E8DCC8" stroke="#FDFAF5" strokeWidth="1.2" />
          ))}
        </g>
        {point && <circle cx={point.x} cy={point.y} r="7" fill="#C9822F" stroke="#2F1C10" strokeWidth="2" />}
      </svg>
      <div style={{ marginTop: 8, display: 'flex', alignItems: 'center', gap: 12 }}>
        <span style={{ fontSize: 12, color: '#666' }}>
          {point ? `x: ${point.x}, y: ${point.y}` : 'Nessun punto impostato — clicca sulla mappa.'}
        </span>
        {point && (
          <button type="button" onClick={handleClear} disabled={disabled} style={{ fontSize: 12 }}>
            Rimuovi punto
          </button>
        )}
      </div>
      {error && (
        <p style={{ color: '#d02b20', fontSize: 12, marginTop: 4 }}>
          {typeof error === 'string' ? error : formatMessage(error)}
        </p>
      )}
    </div>
  );
});

export default MapPointInput;
